SELECT cr.cr_returned_date_sk, cr.cr_return_quantity, cr.cr_return_amount, cr.cr_return_tax, cr.cr_return_amount + cr.cr_return_tax AS total_return_inc_tax, cr.cr_return_quantity * 2 AS double_quantity, CASE WHEN cr.cr_return_amount > 12.87 THEN 'High' ELSE 'Low' END AS amount_category, c.c_customer_id, c.c_birth_year, CASE WHEN c.c_birth_year < 1978 THEN 'Older' ELSE 'Younger' END AS age_group, c.c_birth_country FROM catalog_returns cr JOIN customer c ON cr.cr_refunded_customer_sk = c.c_customer_sk WHERE cr.cr_returned_date_sk = 2451142 AND c.c_birth_country = 'BAHRAIN'
